import{_ as a,o as i,c as s,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Sistema de profesiones","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/overview.md","filePath":"es/guide/professions/overview.md"}'),o={name:"es/guide/professions/overview.md"};function t(n,e,d,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="profession-system" tabindex="-1">Sistema de profesiones <a class="header-anchor" href="#profession-system" aria-label="Enlace permanente a &quot;Sistema de profesiones&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Una profesión forma parte de tu personaje aventurero, dentro del presupuesto común de habilidades.</li><li>Aprende procesos y técnicas; practica la ejecución y construye una reputación.</li><li>El trabajo útil desde el principio, el descubrimiento y los encargos deben importar más allá de alcanzar la habilidad máxima.</li></ul><p><span id="professions-in-syrolands"></span><span id="at-a-glance"></span><span id="crafts-belong-to-adventurers"></span><span id="learning-and-becoming-known"></span><span id="knowledge-and-production"></span><span id="shared-character-rules"></span><span id="inscription-and-magical-knowledge"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Skill (habilidad)</td><td>Capacidad general y consistencia dentro del mismo presupuesto del personaje que las demás habilidades.</td></tr><tr><td>Technique (técnica)</td><td>Métodos aprendidos como Destilación o fabricación de arcos; no son recompensas automáticas por puntuación.</td></tr><tr><td>Profession Path (camino profesional)</td><td>Combina habilidades, técnicas y práctica para desarrollar una especialización.</td></tr><tr><td>Conocimiento e identidad</td><td>Los diarios registran descubrimientos; los productos reales y los encargos construyen la reputación.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Las habilidades de fabricación ya comparten el presupuesto del personaje.</td><td>Las funciones de campo, supervivencia y exploración animan a llevar un oficio a las aventuras.</td></tr><tr><td>Las herramientas, los materiales y las tiradas de habilidad sostienen los ciclos de fabricación conocidos.</td><td>Los procesos interactivos, el conocimiento aprendido y la ejecución definen los resultados.</td></tr><tr><td>UO posterior incluye aprendizaje de recetas y Bulk Order Deeds.</td><td>El descubrimiento y los encargos funcionales destacan la adecuación al uso y la reputación.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a> · <a href="https://uo.com/wiki/ultima-online-wiki/skills/tailoring/" target="_blank" rel="noreferrer">Tailoring</a>.</p><h2 id="explore-the-professions" tabindex="-1">Explora las profesiones <a class="header-anchor" href="#explore-the-professions" aria-label="Enlace permanente a &quot;Explora las profesiones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profesión</th><th>Función</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/es/guide/professions/cooking.html">Cocina</a></td><td>Comida y supervivencia</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alquimia</a></td><td>Reacciones y preparados</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/mining.html">Minería</a></td><td>Geología y extracción</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Herrería</a></td><td>Metal y mantenimiento</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/tailoring.html">Sastrería</a></td><td>Protección flexible y moda</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Tala</a></td><td>Madera y tala</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpintería</a></td><td>Trabajo de madera y fabricación de arcos aprendida</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/tinkering.html">Mecánica</a></td><td>Mecanismos y seguridad</td></tr><tr><td><a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscripción</a></td><td>Notación y referencias mágicas</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un explorador con Herrería podría mantener equipo y hacerse conocido por sus armas de campo fiables, sin convertirse en un personaje dedicado solo al taller.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>La dirección actual es de unos 700 puntos totales de habilidad y normalmente 100 por habilidad. Los personajes útiles no necesitan maximizar siete habilidades.</li><li>El descubrimiento manual establece el dominio; el trabajo conocido puede repetirse en lotes en una estación, con tiempo y materiales reales. El movimiento, el combate o la pérdida de la estación pueden interrumpir la producción.</li><li>El conocimiento puede compartirse, pero la ejecución no puede copiarse. Los umbrales de producción y las reglas de enseñanza y encargos siguen abiertos.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades y progresión</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p>',20)])])}const m=a(o,[["render",t]]);export{h as __pageData,m as default};
